<h2><?=$title?></h2><div class="card"><div class="card-body"><?=form_open()?><div class="row"><div class="col-md-6 mb-3"><label class="form-label">Master Agreement</label><select required class="form-select" name="agreement_id" <?= $so?'disabled':'' ?>><option value="">Pilih Agreement</option><?php foreach($agreements as $a):?><option value="<?=$a->agreement_id?>" <?=($so&&$so->agreement_id==$a->agreement_id)?'selected':''?>><?=html_escape($a->agreement_number)?></option><?php endforeach;?></select><?php if($so):?><input type="hidden" name="agreement_id" value="<?=$so->agreement_id?>"><?php endif;?></div><div class="col-md-6 mb-3"><label class="form-label">Cost Centre</label><select required class="form-select" name="cost_centre_id"><?php foreach($centres as $c):?><option value="<?=$c->cost_centre_id?>" <?=($so&&$so->cost_centre_id==$c->cost_centre_id)?'selected':''?>><?=html_escape($c->cost_centre_name)?></option><?php endforeach;?></select></div><div class="col-md-6 mb-3"><label class="form-label">Aktivitas</label><input required class="form-control" name="activity" value="<?=html_escape($so->activity??'')?>"></div><div class="col-md-6 mb-3"><label class="form-label">Work Period</label><input required class="form-control" name="work_period" value="<?=html_escape($so->work_period??'')?>"></div></div><?php if(!$so):?><h5>Item BOQ</h5><table class="table"><tr><th>Part Number</th><th>Deskripsi</th><th>Harga</th><th>Qty Plan</th></tr><?php foreach($boqs as $b):?><tr><td><?=$b->part_number?></td><td><?=$b->description?></td><td><?=rupiah($b->unit_price)?></td><td><input class="form-control" type="number" min="0" step="0.01" name="qty[<?=$b->boq_id?>]"></td></tr><?php endforeach;?></table><?php endif;?><button class="btn btn-primary">Simpan</button><a class="btn btn-light" href="<?=site_url('service-orders')?>">Batal</a><?=form_close()?></div></div>
